<script setup>
import {ref,watch,onMounted,onBeforeUnmount,nextTick} from 'vue';
import {request} from './workbench-api';
const props=defineProps({bases:{type:Array,default:()=>[]},initialDocument:{type:Object,default:null}});
const emit=defineEmits(['task','document','compare']);
const base=ref('automotive'),text=ref(''),image=ref(''),fileName=ref(''),published=ref(false),translate=ref(true),useDescriptions=ref(true),busy=ref(false),error=ref(''),result=ref(null),health=ref(null),observation=ref(null),selected=ref(null);let seq=0,fileSequence=0;
watch([base,text,image,published,translate,useDescriptions],()=>{seq++;result.value=null;observation.value=null;selected.value=null;});
onBeforeUnmount(()=>{seq++;fileSequence++;});
watch(()=>props.initialDocument,async doc=>{if(!doc)return;base.value=doc.knowledge_base_id||base.value;await nextTick();await inspect(doc);},{immediate:true});
onMounted(async()=>{try{health.value=await request('/multimodal/status');}catch(e){error.value=e.message;}});
async function choose(e){const fileToken=++fileSequence;image.value='';fileName.value='';error.value='';const file=e.target.files[0];if(!file)return;if(file.size>8*1024*1024){error.value='查询图片最大 8 MiB';return;}const reader=new FileReader();reader.onload=()=>{if(fileSequence!==fileToken)return;image.value=String(reader.result).split(',')[1];fileName.value=file.name;};reader.onerror=()=>{if(fileSequence===fileToken)error.value='图片读取失败';};reader.readAsDataURL(file);}
async function search(){const token=++seq;busy.value=true;error.value='';result.value=null;observation.value=null;try{const r=await request('/multimodal/search',{method:'POST',body:{knowledge_base_id:base.value,text:text.value,image_base64:image.value,review_mode:published.value?'published_only':'reference',top_k:8,cross_language_query:translate.value,description_retrieval:useDescriptions.value}});if(seq===token)result.value=r;}catch(e){if(seq===token)error.value=e.message;}finally{busy.value=false;}}
async function inspect(doc){const token=++seq;selected.value=doc;observation.value=null;try{const r=await request(`/documents/${doc.document_id}/visual-observations`);if(seq===token){if(r.revision_id&&doc.revision_id&&r.revision_id!==doc.revision_id){selected.value=null;error.value='来源版本已变化，请刷新资料后重新查看。';return;}observation.value=r;}}catch(e){if(seq===token)error.value=e.message;}}
async function describe(){if(!selected.value)return;busy.value=true;try{const r=await request('/tasks',{method:'POST',body:{kind:'vision_describe',document_ids:[selected.value.document_id],knowledge_base_id:base.value}});emit('task',r.task_id);}catch(e){error.value=e.message;}finally{busy.value=false;}}
const channel={text_image:'文字与画面语义',image_image:'新图片与库内图片',source_ocr_text:'来源文字 / OCR',visual_description_text:'模型可见内容描述',source_reviewed_visual_text:'AI 已核对的画面标签'};
</script>
<template><section class="wb-card"><small>MULTIMODAL SEARCH</small><h2>图文联合检索</h2><p>使用现有预训练模型查找画面或相似图片。请选择知识库，查询图片只用于本次检索。</p><form @submit.prevent="search"><label class="wb-field">知识库<select v-model="base" aria-label="图文知识库"><option v-for="b in bases" :key="b.id" :value="b.id">{{b.name}}</option></select></label><label class="wb-field">画面描述<input v-model="text" maxlength="4000" placeholder="例如：机械臂、车身和焊接火花"/></label><label class="wb-field">上传查询图片（可选，最大 8 MiB）<input type="file" accept="image/*" @change="choose"/></label><p v-if="fileName">{{fileName}} <button type="button" class="wb-button tiny" @click="image='';fileName=''">移除查询图片</button></p><label><input type="checkbox" v-model="translate"/>中文画面描述先由本机模型译为英文检索</label><label><input type="checkbox" v-model="useDescriptions"/>使用已检查的可见内容描述</label><label><input type="checkbox" v-model="published"/>只检索已审核发布资料</label><p class="wb-muted">当前知识库图文向量：{{health?.indexed_by_base?.[base]??'—'}} 份；可见内容描述 {{health?.described_by_base?.[base]??0}} 份，来源与边界检查 {{health?.screened_by_base?.[base]??0}} 份。图像向量使用首帧；动态图的可解码首、中、末帧描述可参与文字检索。</p><button class="wb-button primary" :disabled="busy||(!text.trim()&&!image)">{{busy?'本地检索中…':'查找图文'}}</button></form><div v-if="error" role="alert" class="wb-alert error">{{error}}</div><p v-if="result&&!result.items.length" class="wb-empty">当前范围没有可用图文索引。可在任务中心预建图文语义向量，或查看审核状态。</p><p v-if="result?.query_translation" class="wb-muted">本次检索译文：{{result.query_translation.text}}（译文不作来源依据）</p><p v-if="result?.trace_id" class="wb-muted">Trace {{result.trace_id}} · {{result.latency_ms?.total}} ms</p><p v-if="result" class="wb-muted">{{result.indexed_documents}} 份可用图片 · 排名分数用于比较相似程度，不是事实置信度。</p><div class="wb-image-gallery"><article v-for="doc in result?.items||[]" :key="doc.document_id" class="wb-image-card"><img style="width:100%;height:180px;object-fit:contain" :src="`/api/v2/workbench/documents/${doc.document_id}/preview?revision_id=${doc.revision_id}`" :alt="doc.source_caption"/><strong>{{doc.source_caption}}</strong><p v-for="m in doc.matches" :key="m.channel">{{channel[m.channel]}} · 第 {{m.rank}} · {{m.raw_score.toFixed(4)}}<span v-if="m.evidence_text"> · 画面依据：{{m.evidence_text}}（{{m.evidence_review_id}}）</span></p><div class="wb-actions"><button class="wb-button tiny" @click="emit('document',doc)">原图与 OCR 依据</button><button class="wb-button tiny" @click="inspect(doc)">视觉观察</button><button class="wb-button tiny" @click="emit('compare',doc)">区域对照</button></div></article></div></section><section v-if="selected" class="wb-card"><h3>视觉观察与 AI 审核</h3><p>模型文字不等于 OCR，预测区域不等于精确单元格定位。此记录不能作为缺陷根因或质量放行结论。</p><button class="wb-button" :disabled="busy" @click="describe">为当前图片生成观察记录</button><button class="wb-button" @click="inspect(selected)">刷新记录</button><div v-for="entry in observation?.items||[]" :key="entry.fingerprint"><p v-if="entry.ai_review"><strong>AI 审核：{{entry.ai_review.decision}}</strong> · {{entry.ai_review.note}}</p><p v-else-if="entry.ai_screening">AI 已检查来源绑定与描述边界；画面细节仍为模型观察。<span v-if="entry.ai_screening.flags.length">标记：{{entry.ai_screening.flags.join(' / ')}}</span></p><p v-else>模型原始观察，尚未完成来源复核。</p><p>{{entry.observation.visible_description}}</p><details v-if="entry.frame_samples?.length"><summary>动态图采样观察 · {{entry.frame_samples.length}} 帧（非逐帧语义识读）</summary><article v-for="frame in entry.frame_samples" :key="frame.frame_index"><p>帧 {{frame.frame_index+1}} / {{frame.frame_count}} · {{frame.timestamp_ms}} ms</p><img style="max-width:100%;max-height:320px;object-fit:contain" :src="`/api/v2/workbench/documents/${selected.document_id}/visual-frames/${frame.frame_index}/preview?fingerprint=${encodeURIComponent(entry.fingerprint)}`" alt="绑定来源的动态图采样帧" loading="lazy"/><p>{{frame.observation.visible_description}}</p><p v-if="frame.source_recovery">当前观察含经原件字节前缀核验的恢复副本；原件保留。</p><p v-if="frame.source_decode_failures?.length">来源含 {{frame.source_decode_failures.length}} 个无法解码的帧，未补造画面。</p></article></details><p>可见文字候选：{{entry.observation.visible_text?.join(' / ')}}</p><ul><li v-for="u in entry.observation.unknowns" :key="u">未知：{{u}}</li></ul><div style="position:relative;max-width:700px"><img style="width:100%;display:block" :src="`/api/v2/workbench/documents/${selected.document_id}/preview?revision_id=${selected.revision_id}`" alt="模型区域与原图对照"/><div v-for="(region,i) in entry.observation.regions" :key="i" :title="region.observation" :style="{position:'absolute',border:'2px solid #ed8b20',boxSizing:'border-box',left:region.bbox[0]*100+'%',top:region.bbox[1]*100+'%',width:(region.bbox[2]-region.bbox[0])*100+'%',height:(region.bbox[3]-region.bbox[1])*100+'%'}"><span style="background:#fff;color:#222">{{i+1}} {{region.label}}</span></div></div><ul><li v-for="(region,i) in entry.observation.regions" :key="i">{{i+1}}：{{region.observation}}（区域为模型预测）</li></ul></div><p v-if="observation&&!observation.items.length">暂无当前版本观察记录。</p></section></template>

<style scoped>form>label:not(.wb-field){display:flex;align-items:center;gap:8px;margin:12px 0}form>label:not(.wb-field) input{width:16px;height:16px;margin:0;flex:0 0 auto}p,li,strong{overflow-wrap:anywhere}</style>
